/**
 * post-commit-template — the git hook body, as CODE rather than a data file.
 *
 *, re-learned the hard way on 2026-09-07: `loadTemplate()` read this text
 * with a `__dirname`-relative `fs.readFileSync`. That works from an npm install
 * and DIES in the esbuild single-file bundle, which inlines JavaScript and knows
 * nothing about a `hooks/` directory. The hosted bootstrap therefore installed a
 * working observer and NO git hook, printing one best-effort note that nobody
 * read — commit capture was quietly absent on every bundle-installed device.
 *
 * The fix is the same one the harness catalog already carries in its docblock:
 * a packaged data file that the runtime must read is a liability; make it code.
 * `hooks/post-commit.template` remains on disk as the human-editable source and
 * is pinned byte-for-byte to this constant by `hook-template-parity.test.ts`,
 * so the two can never drift.
 *
 * GENERATED from hooks/post-commit.template — edit the template, then re-run
 * `npm run generate:hook-template`.
 */

export const POST_COMMIT_TEMPLATE: string = "#!/bin/sh\n# --- Provian PE Hook Start ---\n# Generates a Provenance Envelope for every commit.\n# Disable: export PROVIAN_DISABLE_HOOK=1\n# Uninstall: \"$HOME/.provian/bin/provian\" uninstall (hosted install), or the SDK's `setup-hook --remove`\n\nif [ \"$PROVIAN_DISABLE_HOOK\" = \"1\" ]; then\n  exit 0\nfi\n\n# If the provian-observer is running AND its GitPlugin is actively watching\n# THIS repo, let the observer handle the commit (prevents double-counting).\n# The observer publishes the repo roots it watches to observer-git-repos. It\n# runs with cwd=$HOME and typically watches nothing, so for most repos this set\n# does NOT contain the repo — and the hook must fire, or the commit is dropped\n# by both. Defer only when this repo's root is in the watched set.\nif [ -f \"$HOME/.provian/observer.pid\" ]; then\n  OBSERVER_PID=$(cat \"$HOME/.provian/observer.pid\" 2>/dev/null)\n  if [ -n \"$OBSERVER_PID\" ] && kill -0 \"$OBSERVER_PID\" 2>/dev/null; then\n    PROVIAN_WATCHED=\"$HOME/.provian/observer-git-repos\"\n    PROVIAN_REPO_ROOT=$(git rev-parse --show-toplevel 2>/dev/null)\n    if [ -n \"$PROVIAN_REPO_ROOT\" ] && [ -f \"$PROVIAN_WATCHED\" ] && \\\n       grep -qxF \"$PROVIAN_REPO_ROOT\" \"$PROVIAN_WATCHED\" 2>/dev/null; then\n      exit 0\n    fi\n  fi\nfi\n\n# Skip rebases, amends, cherry-picks - would double-count work\nif echo \"$GIT_REFLOG_ACTION\" | grep -qi \"rebase\\|amend\\|cherry-pick\"; then\n  exit 0\nfi\n\n# The hook names only WHICH commit it witnesses — the sha, captured here\n# synchronously, before the report is backgrounded, so `git commit -m a && git\n# commit -m b` names a and b, never b twice. `report-pe --hook post-commit`\n# reads everything else (branch, changed files/lines) from git itself, and\n# records the named commit only when git shows it exists, is reachable from\n# HEAD, and was committed moments ago. commit_sha is the (user, commit_sha)\n# cross-witness mint-once key shared with the observer's GitPlugin and the forge\n# webhook, so whichever path witnesses a commit, exactly one mints. Manual\n# reporting was removed: an actor's own claim about its work is never a\n# Provenance Envelope.\nCOMMIT_SHA=$(git rev-parse HEAD 2>/dev/null)\n\n# Persistent local log\nPROVIAN_DIR=\"$HOME/.provian\"\nHOOK_LOG=\"$PROVIAN_DIR/hook.log\"\nmkdir -p \"$PROVIAN_DIR\"\n\n# Report PE asynchronously - never blocks commits\nif [ -n \"$COMMIT_SHA\" ]; then\n  ({{REPORT_PE_CMD}} --hook post-commit --commit-sha \"$COMMIT_SHA\" >>\"$HOOK_LOG\" 2>&1 &)\nfi\n\n# Composition (WS3): chain to the repo's OWN .git/hooks/post-commit that a global\n# core.hooksPath diverted git away from — but ONLY when this hook is running as\n# the GLOBAL Provian hook (~/.provian/hooks). When Provian was appended INTO a\n# repo's own hooksPath (Husky / lefthook / .githooks), git already ran that path's\n# other content, so chaining here would DOUBLE-run it. Never run a post-commit that\n# carries our marker (no self- or mutual-recursion), and a chained hook's failure\n# never fails the commit (post-commit is advisory).\nPROVIAN_HOOK_DIR=$(cd \"$(dirname \"$0\")\" 2>/dev/null && pwd)\nif [ \"$PROVIAN_HOOK_DIR\" = \"$HOME/.provian/hooks\" ]; then\n  PROVIAN_REPO_ROOT=$(git rev-parse --show-toplevel 2>/dev/null)\n  PROVIAN_DEFAULT_HOOK=\"$PROVIAN_REPO_ROOT/.git/hooks/post-commit\"\n  if [ -n \"$PROVIAN_REPO_ROOT\" ] && [ -x \"$PROVIAN_DEFAULT_HOOK\" ] && \\\n     ! grep -q \"Provian PE Hook Start\" \"$PROVIAN_DEFAULT_HOOK\" 2>/dev/null; then\n    \"$PROVIAN_DEFAULT_HOOK\" || true\n  fi\nfi\n# --- Provian PE Hook End ---\n";
